begin;
create extension if not exists pgtap with schema extensions;
select plan(9);
insert into auth.users (id, email) values ('00000000-0000-0000-0000-0000000000e2', 'photos-staff@example.com');
insert into people (name, kind, auth_user_id, is_staff) values ('Photos staff', 'staff', '00000000-0000-0000-0000-0000000000e2', true);
insert into items (name, kind) values ('Photos survivor', 'portable'), ('Photos loser', 'portable');
insert into assets (item_id, tag) select id, 'PHOTO-001' from items where name = 'Photos loser';
select has_table('public', 'item_photos', 'photo table exists');
select ok(not has_table_privilege('anon', 'public.item_photos', 'select'), 'anon cannot select');
select lives_ok($$insert into item_photos (item_id, path) select id, 'reference.jpg' from items where name = 'Photos loser'$$, 'reference photo inserts');
select throws_ok($$insert into item_photos (item_id, asset_id, path) select i.id, a.id, 'mismatch.jpg' from items i, assets a where i.name = 'Photos survivor' and a.tag = 'PHOTO-001'$$, '23503', null, 'asset item must match');
select throws_ok($$insert into item_photos (item_id, path, state) select id, 'bad.jpg', 'foo' from items where name = 'Photos loser'$$, '23514', null, 'invalid state rejected');
select lives_ok($$update assets set condition = 'disassembled' where tag = 'PHOTO-001'$$, 'disassembled condition accepted');
insert into item_photos (item_id, asset_id, path) select item_id, id, 'asset.jpg' from assets where tag = 'PHOTO-001';
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-0000000000e2","role":"authenticated"}';
select lives_ok($$select merge_items((select id from items where name = 'Photos survivor'), array[(select id from items where name = 'Photos loser')])$$, 'merge succeeds');
select is((select count(*) from item_photos where path in ('reference.jpg', 'asset.jpg') and item_id = (select id from items where name = 'Photos survivor')), 2::bigint, 'both photos move to survivor');
select throws_ok($$insert into item_photos (item_id, path) select id, 'reference.jpg' from items where name = 'Photos survivor'$$, '23505', null, 'path is unique');
select * from finish();
rollback;
